import assert from "node:assert/strict";
import {execFileSync} from "node:child_process";
import {runOmpWorkerResult} from "C:\\Users\\assas\\Documents\\The-Second-Brain\\.worktrees\\v2-one-shot\\brainstem\\prime-extension\\src\\worker-result-bridge.ts";
const home="C:\\Users\\assas\\AppData\\Local\\Temp\\brain-closeout-baseline-20260905T030605Z-audited-closeout\\receipt-smoke-home";
const python="C:\\Users\\assas\\Documents\\The-Second-Brain\\.worktrees\\v2-one-shot\\.venv\\Scripts\\python.exe";
const env={...process.env,SECOND_BRAIN_HOME:home}; delete env.PYTHONHOME; delete env.PYTHONPATH;
execFileSync(python,["-c","from pathlib import Path; from second_brain import db; db.migrate(db.db_path(Path("+JSON.stringify(home)+")))"],{env,cwd:home});
const outcomes=[];
for(const status of ["completed","failed","cancelled"] as const){
 const sessionId="receipt-smoke-parent"; const taskId="receipt-smoke-"+status+"-"+crypto.randomUUID();
 const context=JSON.parse(execFileSync(python,["-m","second_brain","autoinject","omp-routing"],{env,cwd:home,encoding:"utf8",input:JSON.stringify({operation:"worker_context",host_session_id:sessionId,task_id:taskId,task:"Inspect bounded local evidence",scope:"repository",completion_condition:"Return evidence",project_id:"receipt-smoke",role:"driver",provider:"openai-codex",model:"gpt-5.6-luna",worker_role:"worker",context_refs:[]})}));
 assert.equal(context.status,"prepared");
 const options={home,python,sessionId,taskId,packetSha256:context.packet_sha256,status,workerAgent:"smoke-worker",summary:"Observed "+status};
 const first=await runOmpWorkerResult(options); const replay=await runOmpWorkerResult(options);
 assert.equal(first.ok,true,JSON.stringify(first));assert.equal(first.status,status);assert.equal(replay.resultSha256,first.resultSha256);
 const wrong=await runOmpWorkerResult({...options,sessionId:"other-parent"}); assert.equal(wrong.ok,false);
 outcomes.push({status,first,replay,wrongParentRejected:!wrong.ok});
}
console.log(JSON.stringify({offlineOnly:true,outcomes},null,2));
